const questions = topics.flatMap(({ name: category, source, questions: items }) =>
  items.map(({ prompt, answer, explanation, aliases }, index) => ({
    id: `${category.toLowerCase().replace(/[^a-z]+/g, "-")}-${String(index + 1).padStart(2, "0")}`,
    category,
    source,
    question: prompt,
    answer,
    explanation,
    acceptedAnswers: aliases
  }))
);

module.exports = { topics: topics.map(({ name }) => name), questions };
